from taf.internal.execution.base import CreatingExecutor
from taf.internal.file.transfer.base import CreatingFileGetter
from taf.internal.execution.base.executor_config import migrate_configuration
from .collector import SimpleCollector
from taf.collectors.core.factories.factory import Factory
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SimpleCollectorFactory(
        CreatingFileGetter(  # type: ignore[misc]
            'file_getter', 'file_getter'),
        CreatingExecutor(  # type: ignore[misc]
            'tool_executor', 'executor'),
        CreatingExecutor(  # type: ignore[misc]
            'local_executor', None),
        Factory):
    """
    factory to create simple collectors
    """
    _optional_parameters = {"file_pattern", "options", "target_file_name"}
    _mandatory_parameters = {"dir_path", "name"}
    _product_class = SimpleCollector

    def create(self, configuration, existing_arguments=None):
        configuration = migrate_configuration(configuration)
        configuration['file_getter'] = {'type': 'cat',
                                        'executor': configuration.get(
                                            'executor', {})}
        return super().create(configuration, existing_arguments)
